"""Brute-force reference implementation for differential testing."""
import json, heapq

class Ref:
    def __init__(self, cfg):
        self.idle_timeout=cfg["idle_timeout"]
        self.packet_limit=cfg["packet_limit"]
        self.W=cfg["prefix_width"]
        self.rules=[(r["id"],r["class"],r["priority"],r["ranges"]) for r in cfg["rules"]]
        self.fb=cfg["fallback"]
        self.flows={}   # fid -> dict
        self.last_time=-1

    def backup_class(self,f):
        feats=f["first"]
        feats=feats+[0]*(self.W-len(feats))
        node=self.fb
        while "class" not in node:
            if feats[node["feature"]]<=node["threshold"]:
                node=node["le"]
            else:
                node=node["gt"]
        return node["class"]

    def expire(self,T):
        thr=T-self.idle_timeout
        expired=[]
        for fid,f in self.flows.items():
            if not f["decided"] and f["last"] < thr:
                expired.append(fid)
        expired.sort()
        ev=[]
        for fid in expired:
            f=self.flows[fid]
            cls=self.backup_class(f)
            f["decided"]=True; f["cls"]=cls; f["reason"]="idle"; f["rule"]=None
            ev.append({"type":"decision","flow":fid,"class":cls,"reason":"idle","at":f["n"],"time":T,"rule":None})
        return ev

    def add_packet(self,f,src,L,T):
        if f["fwd"] is None:
            f["fwd"]=src
        v=L if src==f["fwd"] else -L
        f["feats"].append(v)
        f["n"]+=1
        f["last"]=T
        if len(f["first"])<self.W: f["first"].append(v)
        n=f["n"]
        ev=[]
        matches=[]
        for (rid,cls,prio,ranges) in self.rules:
            k=len(ranges)
            if k<=n:
                ok=True
                for i in range(k):
                    lo,hi=ranges[i]
                    if not (lo<=f["feats"][n-k+i]<=hi):
                        ok=False; break
                if ok:
                    matches.append((rid,cls,prio,k,n-k))
        matches.sort(key=lambda x:x[0])
        for (rid,cls,prio,k,start) in matches:
            ev.append({"type":"match","flow":f["fid"],"rule":rid,"start":start,"end":n})
            f["mcount"]+=1
        if matches and not f["decided"]:
            best=None
            for (rid,cls,prio,k,start) in matches:
                key=(prio,k,-rid)
                if best is None or key>best[0]:
                    best=(key,rid,cls)
            _,brid,bcls=best
            f["decided"]=True; f["cls"]=bcls; f["reason"]="key"; f["rule"]=brid
            ev.append({"type":"decision","flow":f["fid"],"class":bcls,"reason":"key","at":n,"time":T,"rule":brid})
        if not f["decided"] and n>=self.packet_limit:
            cls=self.backup_class(f)
            f["decided"]=True; f["cls"]=cls; f["reason"]="packet_limit"; f["rule"]=None
            ev.append({"type":"decision","flow":f["fid"],"class":cls,"reason":"packet_limit","at":n,"time":T,"rule":None})
        return ev

    def handle(self,req):
        op=req["op"]
        if op=="open":
            fid=req["flow"]; T=req["time"]
            if T<self.last_time: raise ValueError("time")
            if fid in self.flows: raise ValueError("dup")
            if len(self.flows)>=4096: raise ValueError("live")
            ev=self.expire(T)
            self.flows[fid]={"fid":fid,"last":T,"n":0,"fwd":None,"decided":False,"cls":None,"reason":None,"rule":None,"mcount":0,"feats":[],"first":[]}
            self.last_time=T
            return {"events":ev}
        if op=="tick":
            T=req["time"]
            if T<self.last_time: raise ValueError("time")
            ev=self.expire(T); self.last_time=T
            return {"events":ev}
        if op=="close":
            fid=req["flow"]; T=req["time"]
            if T<self.last_time: raise ValueError("time")
            if fid not in self.flows: raise ValueError("absent")
            ev=self.expire(T)
            f=self.flows[fid]
            if not f["decided"]:
                cls=self.backup_class(f)
                f["decided"]=True; f["cls"]=cls; f["reason"]="end"; f["rule"]=None
                ev.append({"type":"decision","flow":fid,"class":cls,"reason":"end","at":f["n"],"time":T,"rule":None})
            ev.append({"type":"closed","flow":fid,"packets":f["n"],"matches":f["mcount"],"class":f["cls"],"reason":f["reason"],"rule":f["rule"]})
            del self.flows[fid]; self.last_time=T
            return {"events":ev}
        if op=="chunk":
            ev=[]
            for p in req["packets"]:
                fid=p["flow"]; t=p["time"]; src=p["source"]; L=p["length"]
                if t<self.last_time: raise ValueError("time")
                if fid not in self.flows: raise ValueError("absent")
                ev.extend(self.expire(t))
                ev.extend(self.add_packet(self.flows[fid],src,L,t))
                self.last_time=t
            return {"events":ev}
        raise ValueError("op")
PYEOF
